// xcorr A.raw N.raw nStart nDur
// Raw mono f32 at 2 kHz. Finds where N[nStart, nStart+nDur) best matches in A,
// by normalized correlation. Prints: bestStartInA score
import Foundation

func load(_ p: String) -> [Float] {
    let d = FileManager.default.contents(atPath: p)!
    return d.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
}
let a = load(CommandLine.arguments[1]), n = load(CommandLine.arguments[2])
let sr = 2000.0
let s0 = Int(Double(CommandLine.arguments[3])! * sr)
let len = Int(Double(CommandLine.arguments[4])! * sr)
let t = Array(n[s0..<min(s0 + len, n.count)])
let tm = t.reduce(0, +) / Float(t.count)
let tc = t.map { $0 - tm }
let tn = sqrt(tc.reduce(0) { $0 + $1 * $1 })
var best = (-1, Float(-2))
if a.count >= tc.count {
    for k in 0...(a.count - tc.count) {
        var m: Float = 0
        for i in 0..<tc.count { m += a[k + i] }
        m /= Float(tc.count)
        var dot: Float = 0, an: Float = 0
        for i in 0..<tc.count { let x = a[k + i] - m; dot += x * tc[i]; an += x * x }
        let r = an > 0 ? dot / (sqrt(an) * tn) : 0
        if r > best.1 { best = (k, r) }
    }
}
print(String(format: "%.4f %.3f", Double(best.0) / sr, best.1))
